const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([-50.925784, 46.694935]);
  const point2 = ee.Geometry.Point([-58.528990, 46.809436]);
  const date = '2019-09-19';

  // 2. Data Acquisition - Sentinel-2 for water color analysis
  const s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .filterBounds(ee.Geometry.Point([-54.726387, 46.752185])) // Center between points
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));

  const colSize = s2Col.size().getInfo();
  console.log(`Sentinel-2 images on ${date}: ${colSize}`);

  if (colSize === 0) {
    console.log("No Sentinel-2 images found for the date.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the best image (least cloudy)
  const image = s2Col.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Cloud masking
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  const maskedImage = maskS2clouds(image);

  // 4. Extract blue band reflectance (B2) for milky water detection
  const blueBand = 'B2'; // 490nm - good for detecting turbidity

  // Get reflectance values at both points
  const val1 = maskedImage.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point1,
    scale: 100,
    maxPixels: 1e9
  }).get(blueBand);

  const val2 = maskedImage.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: point2,
    scale: 100,
    maxPixels: 1e9
  }).get(blueBand);

  const reflectance1 = val1.getInfo();
  const reflectance2 = val2.getInfo();

  console.log(`Point 1 blue reflectance: ${reflectance1}`);
  console.log(`Point 2 blue reflectance: ${reflectance2}`);

  // 5. Validation & Final Answer
  if (reflectance1 === null || reflectance2 === null) {
    console.log("One or both points have no valid data");
    console.log("<answer>C2</answer>");
  } else if (isNaN(reflectance1) || isNaN(reflectance2)) {
    console.log("Invalid reflectance values");
    console.log("<answer>C3</answer>");
  } else {
    // Higher blue reflectance = more milky water (more suspended particles)
    if (reflectance1 > reflectance2) {
      console.log("Point 1 has higher reflectance - more milky");
      console.log("<answer>A</answer>");
    } else {
      console.log("Point 2 has higher reflectance - more milky");
      console.log("<answer>B</answer>");
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
